    /**
     * Tests getting all Lots.
     *
     * @return    Collection
     */
    public List<Lot> testGetAll() throws Throwable {
    LOGGER.info( "LotTest:testGetAll() - Retrieving Collection of Lots:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Lot : " );
    List<Lot> collection  = null;

    try {
        // call the static get method on the LotService
        collection = service.getAllLot();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Lot currEntity  = null;
            Iterator<Lot> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getLotId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

